/**
 * Spin drills (Design_Doc §13): a generated position where the user places
 * `depth` pieces, the last of which is a line-clearing spin of `piece`.
 * Generated by drill/generate.ts, graded by drill/drill.ts.
 */

import { Mino, type Engine } from "@haelp/teto/engine";

import type { LockInfo } from "../game-core/clear";
import type { HintStep } from "../planner/hint";

export const DRILL_PIECES = ["T", "L", "J", "S", "Z", "I"] as const;
export type DrillPiece = (typeof DRILL_PIECES)[number];
export type DrillChoice = DrillPiece | "mixed";
export const DRILL_CHOICES: readonly DrillChoice[] = [...DRILL_PIECES, "mixed"];

/** Pieces placed per drill, spin included: current + 5 previews + hold. */
export const MAX_DEPTH = 7;

/** Board as rows of filled flags, bottom row first (y up, as Triangle). */
export type Grid = boolean[][];

export interface Scenario {
  /** Spin piece this drill trains. */
  piece: DrillPiece;
  /** Pieces to place, the spin included (1 = only the spin). */
  depth: number;
  /** Start board, top-down rows, 'X' = filled (same as test/golden/spins.json). */
  rows: string[];
  current: Mino;
  hold: Mino | null;
  /**
   * Pieces after the current one: the 5 previews, then the ones revealed as
   * the drill is played. Together with hold and current, a 7-bag stream.
   */
  queue: Mino[];
  /** A verified line from the start: `depth` steps, the last one is the spin. */
  solution: HintStep[];
  /** Triangle's classification of the solution's final spin. */
  intended: LockInfo;
  /** What the drill ends in, from Triangle's classification of the solution, e.g. "J-Spin Double Mini". */
  name: string;
  /** Spin core the board was built from (debugging only: J/Z drills use flipped L/S cores, and the fill decides the line count). */
  template: string;
  seed: number;
}

export const BOARD_COLS = 10;

export function gridFromRows(rowsTopDown: readonly string[], height = 40): Grid {
  const rows = [...rowsTopDown].reverse();
  return Array.from({ length: height }, (_, y) => Array.from({ length: BOARD_COLS }, (_, x) => rows[y]?.[x] === "X"));
}

/** Top-down rows down to the highest filled row (empty grid → []). */
export function rowsFromGrid(g: Grid): string[] {
  let top = g.length - 1;
  while (top >= 0 && !g[top]!.some(Boolean)) top--;
  const out: string[] = [];
  for (let y = top; y >= 0; y--) out.push(g[y]!.map((c) => (c ? "X" : ".")).join(""));
  return out;
}

/** Write a grid onto the engine board (filled cells as garbage tiles). */
export function writeGrid(e: Engine, g: Grid): void {
  for (let y = 0; y < e.board.state.length; y++) {
    e.board.state[y] = Array.from({ length: BOARD_COLS }, (_, x) => (g[y]?.[x] ? { mino: Mino.GARBAGE, connections: 0 } : null));
  }
}

/**
 * Put the scenario's start position on an engine: board, hold, previews and
 * the current piece. The engine's own bag continues after the previews.
 */
export function applyScenario(e: Engine, s: Pick<Scenario, "rows" | "current" | "hold" | "queue">): void {
  writeGrid(e, gridFromRows(s.rows, e.board.state.length));
  e.held = s.hold;
  e.holdLocked = false;
  for (let i = 0; i < s.queue.length; i++) e.queue[i] = s.queue[i]!;
  e.initiatePiece(s.current);
}
